import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.parser.CCJSqlParserUtil;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.statement.select.SelectBody;
import net.sf.jsqlparser.statement.select.SelectExpressionItem;

public class PageException extends RuntimeException {
    public PageException(String message, Throwable cause) {
        super(message, cause);
    }
}

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    Statement stmt;
    try {
        stmt = CCJSqlParserUtil.parse(sql);
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    Select select = (Select) stmt;
    SelectBody selectBody = select.getSelectBody();
    if (selectBody != null) {
        String pageSql = selectBody.toString();

        if (offset != null) {
            pageSql = pageSql.replace("ROW_NUMBER() OVER (ORDER BY", "ROW_NUMBER() OVER (ORDER BY 0) AS PAGE_ROW_NUMBER,");
            pageSql = "SELECT TOP " + limit + " * FROM (" + pageSql + ") AS PAGE_TABLE_ALIAS WHERE PAGE_ROW_NUMBER > " + offset;
        }

        return pageSql;
    }

    throw new PageException("无法解析Select查询!");
}

